package net.hivel.islandsrpg.mob;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.drop.DropDefinition; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.attribute.Attribute; import org.bukkit.configuration.ConfigurationSection; import org.bukkit.configuration.file.FileConfiguration; import org.bukkit.entity.*; import org.bukkit.persistence.PersistentDataType; import java.util.*;
public class CustomMobService { protected final IslandsRPGPlugin plugin; protected final Map<String,CustomMobDefinition> mobs=new LinkedHashMap<>(); public CustomMobService(IslandsRPGPlugin p){plugin=p;} public void reload(){FileConfiguration c=ConfigUtil.load(plugin,"mobs.yml"); mobs.clear(); var sec=c.getConfigurationSection("mobs"); if(sec==null)return; for(String id:sec.getKeys(false)){CustomMobDefinition d=parse(id,c.getConfigurationSection("mobs."+id)); if(d!=null)mobs.put(id,d);}} protected CustomMobDefinition parse(String id, ConfigurationSection s){try{EntityType e=EntityType.valueOf(s.getString("entity","ZOMBIE")); Map<String,DropDefinition> drops=new LinkedHashMap<>(); var ds=s.getConfigurationSection("drops"); if(ds!=null) for(String k:ds.getKeys(false)){DropDefinition d=plugin.drops().parse(k,ds.getConfigurationSection(k)); if(d!=null)drops.put(k,d);} return new CustomMobDefinition(id,e,s.getString("display-name",id),s.getString("island","starter"),s.getInt("level",1),s.getDouble("health",20),s.getDouble("damage",1),s.getLong("xp",0),s.getLong("money",0),s.getLong("fragments",0),s.getBoolean("show-health-name",true),s.getBoolean("bossbar.enabled",false),s.getBoolean("glowing",false),s.getBoolean("baby",false),s.getBoolean("silent",false),s.getBoolean("spawning.enabled",false),s.getInt("spawning.max-alive",10),s.getInt("spawning.interval-seconds",30),s.getInt("spawning.amount",1),s.getDouble("spawning.radius",4),s.getStringList("spawning.locations"),drops);}catch(Exception ex){plugin.getLogger().warning("Invalid mob "+id+": "+ex.getMessage()); return null;}} public Collection<CustomMobDefinition> all(){return mobs.values();} public CustomMobDefinition get(String id){return mobs.get(id);} public LivingEntity spawn(String id, Location loc){CustomMobDefinition d=get(id); if(d==null||loc==null||loc.getWorld()==null)return null; if(!loc.getWorld().isChunkLoaded(loc.getBlockX()>>4,loc.getBlockZ()>>4))return null; Entity ent=loc.getWorld().spawnEntity(loc,d.entity()); if(!(ent instanceof LivingEntity le)){ent.remove(); return null;} le.getPersistentDataContainer().set(plugin.key("mob_id"), PersistentDataType.STRING,id); le.getPersistentDataContainer().set(plugin.key("mob_boss"), PersistentDataType.INTEGER,0); le.setRemoveWhenFarAway(true); le.setGlowing(d.glowing()); le.setSilent(d.silent()); if(le instanceof Ageable a && d.baby()) a.setBaby(); if(le.getAttribute(Attribute.MAX_HEALTH)!=null) le.getAttribute(Attribute.MAX_HEALTH).setBaseValue(d.health()); le.setHealth(Math.min(d.health(), le.getAttribute(Attribute.MAX_HEALTH).getBaseValue())); updateName(le,d.displayName(),d.health()); return le;} public String id(LivingEntity e){return e.getPersistentDataContainer().get(plugin.key("mob_id"),PersistentDataType.STRING);} public boolean isCustom(LivingEntity e){return id(e)!=null;} public void updateName(LivingEntity e,String base,double max){String heart=plugin.emojis()?" &c❤ ":" &c"; e.setCustomName(ColorUtil.color(base+heart+Math.max(0,(int)Math.ceil(e.getHealth()))+"/"+(int)Math.ceil(max))); e.setCustomNameVisible(true);} }
